  <script>
  (function() {
    var container = document.querySelector('.product-slider-container');
    if (!container) return;

    var slides = container.querySelectorAll('.product-slide');
    var dots = container.querySelectorAll('.product-slider-dot');
    var prevBtn = container.querySelector('.product-slider-nav.prev');
    var nextBtn = container.querySelector('.product-slider-nav.next');

    var currentSlide = 0;
    var totalSlides = slides.length;
    var autoSlideInterval = null;

    setTimeout(function() {
      var visibleSlides = Array.from(slides).filter(function(slide) {
        var img = slide.querySelector('img');
        return img && img.complete && img.naturalHeight !== 0;
      });

      if (visibleSlides.length === 0) {
        container.style.display = 'none';
      }
    }, 1000);

    function getVisibleSlides() {
      return Array.from(slides).filter(function(slide) {
        var img = slide.querySelector('img');
        return img && img.style.display !== 'none' && slide.style.display !== 'none';
      });
    }

    function showSlide(index) {
      var visibleSlides = getVisibleSlides();
      if (visibleSlides.length === 0) return;

      if (index < 0) index = visibleSlides.length - 1;
      if (index >= visibleSlides.length) index = 0;

      var visibleIndex = 0;
      slides.forEach(function(slide, i) {
        var img = slide.querySelector('img');
        var isVisible = img && img.style.display !== 'none' && slide.style.display !== 'none';

        if (isVisible) {
          slide.classList.toggle('active', visibleIndex === index);
          if (visibleIndex < dots.length) {
            dots[i].classList.toggle('active', visibleIndex === index);
          }
          visibleIndex++;
        } else {
          slide.classList.remove('active');
          if (i < dots.length) {
            dots[i].classList.remove('active');
          }
        }
      });

      currentSlide = index;
    }

    function nextSlide() {
      showSlide(currentSlide + 1);
    }

    function prevSlide() {
      showSlide(currentSlide - 1);
    }

    function startAutoSlide() {
      autoSlideInterval = setInterval(nextSlide, 5000);
    }

    function stopAutoSlide() {
      if (autoSlideInterval) {
        clearInterval(autoSlideInterval);
        autoSlideInterval = null;
      }
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', function() {
        nextSlide();
        stopAutoSlide();
        startAutoSlide();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', function() {
        prevSlide();
        stopAutoSlide();
        startAutoSlide();
      });
    }

    dots.forEach(function(dot, index) {
      dot.addEventListener('click', function() {
        showSlide(index);
        stopAutoSlide();
        startAutoSlide();
      });
    });

    container.addEventListener('mouseenter', stopAutoSlide);
    container.addEventListener('mouseleave', startAutoSlide);

    startAutoSlide();
  })();
